import {MISSIONS} from '../data/campaign.js';
import {canPlayMission,suggestedMission,lockedMessage} from '../core/CampaignAccess.js';
const LOCATIONS=['GRECIA','FOSSANO','TORINO','CUNEO','SOTTERRANEI','FABBRICA','ARCHIVIO','LABORATORIO','ROMA','LA BANDA'];
const POSITIONS=[[87,82],[21,44],[45,18],[15,22],[45,38],[68,21],[72,44],[37,58],[58,70],[36,82]];
const LOCK='<svg class="mission-lock" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5z" fill="none" stroke="currentColor" stroke-width="2.5"/><circle cx="12" cy="15" r="1.5" fill="currentColor"/></svg>';
export function missionNodes(completed,saved,unlockAll=false){return Object.values(MISSIONS).sort((a,b)=>a.id-b.id).map((m,i)=>{const open=canPlayMission(m.id,completed,unlockAll),done=completed.includes(m.id);return `<button type="button" data-mission="${m.id}" style="left:${POSITIONS[i][0]}%;top:${POSITIONS[i][1]}%" class="journey-node ${done?'complete':''} ${open?'available':'locked'}" aria-label="Missione ${m.id}: ${m.name}, ${!open?'bloccata':done?'completata':'giocabile'}" aria-disabled="${!open}"><b>${String(m.id).padStart(2,'0')}</b><small>${!open?LOCK:done?'✓':saved?.mission===m.id?'▶':'◇'}</small></button>`;}).join('');}
export class JourneyMap{
 constructor(app){this.app=app;this.host=document.querySelector('.mission-picker');this.host.innerHTML=`<div class="journey-body"><div class="journey-board" role="group" aria-label="Scegli una delle dieci missioni"><div class="journey-nodes"></div><span class="journey-map-note">GRECIA · PIEMONTE · ROMA</span></div><aside class="journey-detail"><small id="journey-place"></small><h2 id="journey-title"></h2><p id="journey-copy"></p><p id="journey-progress"></p><p id="journey-feedback" class="mission-feedback" role="status" aria-live="polite" hidden></p><div class="difficulty-row"><label for="difficulty">DIFFICOLTÀ</label><select id="difficulty"><option value="easy">Facile · ×1</option><option value="normal" selected>Medio · ×2</option><option value="hard">Difficile · ×3</option><option value="extreme">Extreme · ×4,5</option></select></div><button class="primary" id="start-game">GIOCA LA MISSIONE 01 ↗</button><button class="secondary" id="continue-game" hidden>RIPRENDI IL CHECKPOINT</button><p class="journey-legend">◇ Giocabile · ✓ Completata · 🔒 Da sbloccare<br>Completa le missioni in ordine, poi rigiocale quando vuoi.</p></aside></div>`;this.refresh(true);}
 refresh(recommend=false){const completed=this.app.save.completed(),saved=this.app.save.load();this.host.querySelector('.journey-nodes').innerHTML=missionNodes(completed,saved,this.app.settings?.unlockAllMissions);this.host.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>this.renderSelection(Number(b.dataset.mission)));document.querySelector('#campaign-count').textContent=completed.length+' / 10';const id=recommend?suggestedMission(completed,saved,this.app.settings?.unlockAllMissions):this.app.selectedMission||1;this.renderSelection(id);}
 select(id){this.renderSelection(id);}
 open(){this.refresh(true);this.host.scrollIntoView({behavior:this.app.settings.reduceMotion?'instant':'smooth',block:'start'});this.host.querySelector(`[data-mission="${this.app.selectedMission}"]`)?.focus({preventScroll:true});}
 renderSelection(id){if(!MISSIONS[id])id=1;this.app.selectedMission=Number(id);const m=MISSIONS[id],completed=this.app.save.completed(),saved=this.app.save.load(),open=canPlayMission(id,completed,this.app.settings?.unlockAllMissions),done=completed.includes(Number(id));
 this.host.querySelectorAll('[data-mission]').forEach(b=>{const selected=Number(b.dataset.mission)===Number(id);b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});
 this.host.querySelector('.journey-legend').textContent=this.app.settings?.unlockAllMissions===true?'SBLOCCO LIBERO ATTIVO · Tutte le missioni sono giocabili. Le spunte indicano solo quelle davvero completate.':'◇ Giocabile · ✓ Completata · 🔒 Da sbloccare. Completa le missioni in ordine, poi rigiocale quando vuoi.';
 this.host.querySelector('#journey-place').textContent=LOCATIONS[id-1];this.host.querySelector('#journey-title').textContent=m.name;this.host.querySelector('#journey-copy').textContent=m.chapters[0].intro;this.host.querySelector('#journey-progress').textContent=!open?'🔒 MISSIONE BLOCCATA':done?'✓ MISSIONE COMPLETATA':saved?.mission===Number(id)&&!saved.complete?`CHECKPOINT · CAPITOLO ${saved.chapter+1} / ${m.chapters.length}`:'◇ DISPONIBILE · '+m.chapters.length+' CAPITOLI';
 const feedback=this.host.querySelector('#journey-feedback');feedback.hidden=open;feedback.textContent=open?'':lockedMessage(id,completed);
 const play=this.host.querySelector('#start-game');play.disabled=!open;play.textContent=open?(done?'RIGIOCA':'GIOCA')+' LA MISSIONE '+String(id).padStart(2,'0')+' ↗':'🔒 COMPLETA LE PRECEDENTI';
 const resume=this.host.querySelector('#continue-game');resume.hidden=!open||saved?.mission!==Number(id)||!!saved?.complete;resume.textContent='RIPRENDI IL CHECKPOINT ↗';
 }
}
